/* ===================== Exercise library =====================
 slot: breath | spine | core | balance | floor | shoulders | hips | legs | wrists | mind | video
 equip: [] always possible; 'bar' pull-up bar; 'band' bands/dumbbells; 'floor' a mat or clean floor; 'step' a step/box
 grade: strong | moderate | thin  (strength of the evidence for the reason it is here)
 search: fallback YouTube search when no verified video id is known */
const yt = q => "https://www.youtube.com/results?search_query=" + encodeURIComponent(q);
const EX = [
 {id:"breath_slow",name:"Slow breathing",slot:"breath",secs:{5:60,10:90,15:120},equip:[],grade:"strong",
  search:yt("resonance breathing 6 breaths per minute guide"),
  why:"The nervous-system reset that opens every version of the routine. Six breaths a minute with a long exhale is the single breath practice with consistent physiological evidence, and the same technique works for in-the-moment regulation during the day, so it is worth learning well.",
  protects:["Baseline stress and the morning cortisol spike, turned into focus instead of agitation.","Blood pressure and heart-rate variability, both of which track with long-term cardiovascular health.","The habit itself: a 60-second start is the thing you can always do, which is what keeps a streak of months alive."],
  steps:["Sit or stand tall. Let the shoulders drop and the jaw unclench.","Breathe in through the nose for a count of 4, low into the belly and the sides of the ribs.","Breathe out for a count of 6 to 8, through the nose or softly through the lips. Do not force the end of the exhale.","Keep that rhythm for the whole timer. If counting is distracting, simply make each exhale longer than the inhale.","Finish with one normal breath and notice the difference in the body before moving on."],
  pitfalls:["Pulling air high into the chest and shoulders. The belly should move first.","Holding the breath at the top or bottom; this is a continuous rhythm, not box breathing.","Breathing so slowly you feel air hunger. Six breaths a minute is a target, not a rule; five to seven is fine."],
  evidence:"Voluntary slow breathing at about 6 breaths per minute raises vagally mediated heart-rate variability during and after practice across 223 studies (Laborde 2022). Breathwork as a category shows small-to-moderate effects on stress, anxiety and depression (Fincham 2023, g about 0.3 to 0.4), with moderate risk of bias."},

 {id:"breath_sigh",name:"Cyclic sighing",slot:"breath",secs:{5:60,10:90,15:120},equip:[],grade:"thin",
  search:yt("cyclic sighing physiological sigh technique"),
  why:"An alternative opener for days when slow breathing feels flat. The double inhale re-inflates the small air sacs that collapse overnight, and the long exhale does the same calming work as slow breathing.",
  protects:["Low mood on waking; the one trial found a small daily lift in positive affect that grew over four weeks.","Shallow breathing patterns after sleep."],
  steps:["Sit upright. Inhale through the nose until the lungs feel mostly full.","Without exhaling, take a second short, sharp sniff to the very top.","Exhale slowly through the mouth for 6 to 8 seconds until empty.","Repeat without pausing for the whole timer. Keep the face and shoulders relaxed."],
  pitfalls:["Making the second inhale big; it is a top-off, not a second breath.","Rushing the exhale. The calming effect lives in the long, unforced out-breath.","Doing it lying down and falling back asleep. Sit up."],
  evidence:"One remote trial (Balban 2023, n = 108, 28 days, 5 min/day) found cyclic sighing raised positive affect slightly more than mindfulness and lowered resting respiratory rate; no difference on anxiety, no HRV or heart-rate change, retrospectively registered. Treat as promising, not proven."},

 {id:"catcamel",name:"Cat–camel",slot:"spine",secs:60,equip:["floor"],grade:"moderate",
  search:yt("McGill cat camel exercise"),
  why:"The safest way to wake the spine. Discs are swollen with fluid in the first hour after rising and loaded forward bending stresses them far more then; cat-camel moves every segment through its range with no load at all, which is exactly what the morning calls for.",
  protects:["Morning back injury from bending under load before the discs have settled.","Stiffness in the thoracic spine, which otherwise pushes rotation into the lumbar spine where you do not want it.","A back with recurring nerve pain: if the pain has not been diagnosed, an unloaded warm-up before anything else is the conservative choice. Get it examined."],
  steps:["Hands under shoulders, knees under hips, neck neutral.","Slowly round the whole back toward the ceiling, letting the head drop. Two seconds up.","Slowly let the back sag toward the floor, lifting the head and tailbone. Two seconds down.","8 to 10 cycles. Think of moving one vertebra at a time rather than hinging in the middle.","Stay in the easy range. This is a movement, not a stretch; there should be no sensation of pushing."],
  pitfalls:["Forcing the end ranges. McGill is explicit that pushing the extremes of flexion or extension defeats the purpose.","Moving fast. The warming effect comes from slow, repeated cycles.","Doing it in bed. Get up, move for a few minutes, then do the routine; discs need that time."],
  evidence:"Adams, Dolan and Hutton (Spine 1987) estimated bending stresses on lumbar discs are about 300% higher in the early morning; Snook 1998 (RCT, n = 85) found that avoiding early-morning flexion cut pain by a third in chronic back-pain patients. Cat-camel itself is a McGill clinical staple rather than a trialled intervention."},

 {id:"birddog",name:"Bird dog",slot:"core",secs:60,equip:["floor"],grade:"moderate",
  search:yt("McGill big 3 bird dog"),
  why:"One of the two daily anchors. McGill's research found that back endurance, not back strength, is what separates pain-free spines from painful ones, and the bird dog builds that endurance with almost no spinal load. If you have a back with recurring nerve pain, it is the best-supported thing in this routine, which is why it stays in every version.",
  protects:["Recurrent low-back pain episodes, by training the spine to stay still while the limbs move.","The lumbar spine during lifting, carrying and martial-arts rotation.","Hip extension control; a weak bird dog usually means the lower back is doing the glutes' job."],
  steps:["Hands under shoulders, knees under hips. Brace the belly lightly, as if about to be poked.","Reach one arm forward and the opposite leg back until both are level with the torso. Make a fist and point the heel.","Hold 8 to 10 seconds. Breathe. Nothing in the trunk moves.","Sweep the elbow and knee back together under the body, then extend again. 4 reps per side.","Switch sides. If balance is shaky, start with only the leg, then add the arm."],
  pitfalls:["Lifting the leg above hip height; the lower back arches and the exercise stops working.","Twisting the hips open. Imagine a glass of water on the sacrum.","Holding the breath. Endurance work needs continuous breathing.","Treating it as a treatment for nerve pain. It is protective conditioning; nerve pain itself needs a clinical examination."],
  evidence:"McGill's Big 3 (curl-up, side bridge, bird dog) comes from decades of spine-biomechanics work at Waterloo showing trunk endurance predicts back health better than strength. It is widely used in rehabilitation; the trials are small and clinical rather than large RCTs."},

 {id:"sideplank",name:"Side plank",slot:"core",secs:60,equip:["floor"],grade:"moderate",
  search:yt("McGill side plank big 3"),
  why:"The second daily anchor. It trains the lateral trunk, the muscles that stop the spine from buckling sideways under a load on one arm or one leg, which is most of real life and all of a kick.",
  protects:["Low-back pain, as part of the Big 3 endurance set.","Spine stability in single-leg and asymmetric loading: carrying bags, stepping, kicking, landing.","Shoulder stability on the supporting arm, a small bonus if you work toward handstands."],
  steps:["Lie on one side, elbow under the shoulder, knees bent at first.","Lift the hips so the body forms a straight line from head to knees (or to feet, once strong).","Hold 10 seconds, lower for 3, repeat 4 times. Then switch sides.","Keep the hips stacked and pushed forward; the free hand rests on the opposite shoulder.","Progress by straightening the legs, then by lifting the top leg."],
  pitfalls:["Long single holds. McGill prescribes repeated short holds; endurance builds better and form stays clean.","Letting the hips sag or drift back. The body is one plank.","Shoulder pain: move the elbow directly under the shoulder and press the forearm into the floor."],
  evidence:"Same basis as the bird dog: McGill's Big 3 and the endurance-over-strength finding. Clinical and small-trial evidence; no large RCT."},

 {id:"balance",name:"Single-leg stand",slot:"balance",secs:60,equip:[],grade:"moderate",
  search:yt("single leg balance progression eyes closed"),
  why:"Balance is a skill that decays quietly and matters enormously after 65. A healthy young adult passes every balance test, so the point is to keep the ankles, hips and inner ear talking to each other every day, and to give a foot or ankle recovering from injury a daily workout.",
  protects:["Falls and the fractures they cause in old age, the leading disability pathway you can influence now.","Ankle re-injury; proprioception is what stops a rolled ankle before it happens.","Recovery of a foot or ankle after an injury, once it has healed."],
  steps:["Barefoot, on a firm floor. Pick a point at eye level and keep your eyes on it.","Lift one foot a few centimetres. Arms loose at the sides. Hold 30 seconds.","Switch legs. Breathe normally; drop the shoulders and jaw.","When 30 seconds is easy with eyes open, close the eyes for part of the hold.","Later: stand on a folded towel or cushion, or turn the head slowly while holding."],
  pitfalls:["Gripping the floor with the toes. Let the foot spread and make small, quiet adjustments.","Locking the knee. Keep it soft so the hip can work.","Bracing the whole body. Zhan Zhuang's principle applies: release everything that is not needed."],
  evidence:"In 1,702 adults aged 51–75, failing a 10-second one-leg stand went with 84% higher all-cause mortality over 7 years (Araújo 2022), an association in older people that carries no prognostic information for young adults. Balance training reduces falls in older adults with high certainty (Sherrington 2019 Cochrane)."},

 {id:"sitrise",name:"Floor sit & rise",slot:"floor",secs:60,equip:["floor"],grade:"moderate",
  search:yt("sitting rising test how to"),
  why:"Getting down to the floor and back up without hands combines hip rotation, ankle range, leg power and balance in one movement. It is also the test that predicts survival in middle age, so practising it daily keeps you honest about all four components.",
  protects:["Loss of independence in old age; people who cannot get off the floor stop living on the floor, then stop getting down at all.","Hip and ankle range, the two things that disappear with a desk job.","Leg power, which declines faster than strength with age."],
  steps:["Stand barefoot with space around you. Cross one foot in front of the other.","Lower yourself to a cross-legged sit using as little support as possible: no hands, knees or forearms if you can.","Pause, then stand back up the same way, uncrossing the legs as you rise.","3 to 4 slow repetitions, alternating which leg leads.","Every few weeks, score one attempt: 5 points down, 5 up, minus 1 for each support used, minus 0.5 for a wobble."],
  pitfalls:["Dropping into the sit with momentum. Control on the way down is the whole exercise.","Knee pain on the way up: widen the stance or push lightly off the knee until the legs are stronger.","Chasing the score and forgetting the breath."],
  evidence:"Low scores (0–3) carried 5–6× higher mortality in the 2012 cohort (n = 2,002), and 3.8× natural-cause and 6× cardiovascular mortality in the 2025 follow-up (n = 4,282, mean age 59). Both are one Brazilian clinic and observational; whether improving the score extends life is untested."},

 {id:"hang",name:"Dead hang",slot:"shoulders",secs:60,equip:["bar"],grade:"moderate",
  search:yt("dead hang tutorial beginner"),
  why:"Grip strength is one of the strongest markers of later mortality, and loaded overhead range is what shoulders lose first. A relaxed hang trains both, decompresses the spine and asks nothing of the lower back.",
  protects:["Grip strength, a proxy for overall muscle health that tracks mortality across populations.","Shoulder range and the ability to reach, pull and climb into old age.","Thoracic stiffness after sleep."],
  steps:["Overhand grip, hands shoulder width, thumbs around the bar.","Step off and hang. Let the shoulders rise toward the ears; let the body be heavy.","Breathe slowly for 20 to 30 seconds, step down, rest 20 seconds, repeat until the timer ends.","Once comfortable, add a second phase: pull the shoulder blades down without bending the elbows and hold 5 seconds.","If grip or shoulders are not ready, keep the balls of the feet on the floor and take 20–40% of your weight."],
  pitfalls:["Swinging or kipping. Stillness is the point.","Pinching pain in the front of the shoulder: shift the grip wider or narrower, or unload with the feet. Sharp pain means stop.","Expecting it to cure shoulder pain in ten days. That claim has no evidence."],
  evidence:"Each 5 kg lower grip strength went with 16% higher all-cause mortality in 139,691 adults (PURE, Lancet 2015). The Kirsch claim that hanging remodels the acromion comes from a self-published book with no controlled trials or imaging; hanging is justified as loading, not as a cure."},

 {id:"wall_slide",name:"Wall shoulder slides",slot:"posture",secs:60,equip:[],grade:"thin",
  search:yt("wall slides shoulder mobility"),
  why:"The travel-day replacement for the hang. It takes the shoulders through overhead range while the wall keeps the ribs down and the lower back honest, and it needs nothing but a wall.",
  protects:["Overhead shoulder range on days without a bar.","Rounded upper-back posture after long hours at a desk or screen."],
  steps:["Stand with your back, head and tailbone against a wall, feet a step forward.","Bend the elbows to 90° and press the backs of the hands and forearms to the wall, making a W.","Slide the arms up the wall into a Y, keeping as much contact as you can. 3 seconds up.","Slide back down to the W. 8 to 10 slow reps.","Keep the lower back close to the wall throughout; if it arches, stop the slide lower."],
  pitfalls:["Arching the back to get higher. Height is not the goal; contact is.","Shrugging the shoulders to the ears at the top.","Forcing the forearms flat if the shoulders will not allow it; let them hover and work toward the wall over weeks."],
  evidence:"Practitioner-level. Wall slides appear in most shoulder rehabilitation programmes and are low risk; no outcome trials of the exercise alone."},

 {id:"hip9090",name:"90/90 hip switches",slot:"hips",secs:90,equip:["floor"],grade:"thin",
  search:yt("90 90 hip switches tutorial"),
  why:"Internal and external hip rotation are the ranges a chair takes away first, and when the hips stop rotating, the lumbar spine twists instead. This drill restores both directions while seated on the floor, where the back is safe.",
  protects:["Lower-back twisting strain in walking, kicking and lifting, by giving the femur room to rotate in the socket.","Knee valgus (collapsing inward), which often starts at a stiff hip.","Deep-squat and floor-sitting range."],
  steps:["Sit on the floor. Front leg bent 90° in front of you, back leg bent 90° out to the side, both shins roughly parallel.","Sit tall, hands lightly on the floor or off it. Hinge the chest forward over the front shin for 20 seconds. Breathe.","Come up, then lift both knees and rotate them to the other side without using the hands, settling into the mirror position.","Repeat the forward lean. 4 to 6 switches in total.","If the back knee floats high off the floor, put a cushion under it rather than forcing it down."],
  pitfalls:["A pinch in the front of the front hip: sit on a cushion to raise the hips, or reduce the forward lean. Pinching is a bone-on-bone signal, not a stretch.","Rounding the spine to lean forward. Hinge from the hips with a long back.","Using the hands to switch sides. Letting the hips do it is the strengthening half of the drill."],
  evidence:"Mobility drills reliably improve range of motion in the short term, and strength training through full range does so as well as stretching (Afonso 2021, 11 RCTs). No trial links daily hip mobility work to long-term outcomes."},

 {id:"hipflexor",name:"Half-kneeling hip-flexor stretch",slot:"hips",secs:90,equip:["floor"],grade:"thin",
  search:yt("half kneeling hip flexor stretch posterior pelvic tilt"),
  why:"Length and control at the front of the hip, close to the psoas work physiotherapists commonly prescribe. Done with the pelvis tucked and the glute working, it stretches the hip flexor rather than the lower back.",
  protects:["Anterior pelvic tilt and the lumbar extension strain that comes with it.","Hip extension in walking, running and kicking.","Front-of-hip tightness after long sitting."],
  steps:["Half kneel on a mat: one knee down, the other foot forward, both knees at about 90°.","Squeeze the glute of the kneeling leg and tuck the tailbone under slightly. You may already feel the stretch.","Shift the whole body forward a few centimetres, keeping the tuck. Stop when you feel it in the front of the hip, not the back.","Hold 40 seconds breathing slowly, then switch sides.","Progress by raising the arm on the kneeling side overhead, or by a gentle side bend away."],
  pitfalls:["Lunging far forward with the pelvis tipped. You feel it in the lower back and the hip flexor gets nothing.","Treating a deeper stretch as better. Tendons and nerves dislike aggressive morning stretching; gentle and daily beats hard and occasional.","Assuming this treats nerve pain. The tight-psoas explanation is weakly supported; nerve pain needs a clinical examination, and this stays a comfort and range exercise."],
  evidence:"Stretching improves range of motion acutely and over weeks (Warneke 2024; Afonso 2021). Whether psoas tension compresses lumbar nerves in otherwise healthy people is case-report level at best (StatPearls on the genitofemoral nerve; Merck on lumbosacral radiculopathy)."},

 {id:"armswing",name:"Arm swings (Shuai Shou Gong)",slot:"mind",secs:90,equip:[],grade:"thin",
  search:yt("shuai shou gong arm swinging qigong"),
  why:"The easiest entry into qigong and the most portable: rhythmic, almost meditative, and it loosens shoulders and spine with momentum instead of effort. It is where mind-and-body-at-once begins without having to learn a form.",
  protects:["Shoulder and upper-back stiffness, released through gentle oscillation rather than stretching.","A scattered mind on waking; counting breaths while swinging is attention training in disguise."],
  steps:["Stand feet shoulder width, knees soft, spine long, arms hanging.","Swing both arms forward to about shoulder height and let them fall back behind you. Do not muscle it; let the fall power the next swing.","Keep the shoulders down and the hands loose. Breathe through the nose.","Every fifth swing, dip the knees slightly as the arms go back.","Continue for the whole timer. Count exhales if the mind wanders. Finish by standing still for 20 seconds and noticing the hands."],
  pitfalls:["Swinging high and hard. Low effort, long duration is the practice.","Locking the knees; keep them soft so the whole body bounces gently.","Checking the phone mid-swing. The attention is the exercise."],
  evidence:"No trials of Shuai Shou Gong itself. It borrows from the general qigong evidence (improved balance, blood pressure and sleep in older adults; low-quality trials) and from the breath-attention literature."},

 {id:"calfraise",name:"Single-leg calf raises",slot:"legs",secs:60,equip:[],grade:"moderate",
  search:yt("single leg calf raise technique"),
  why:"The calf and Achilles are the springs for running, jumping and every kick, and calf raises are the usual first safe step after a healed foot injury. Tendons adapt over months, so this earns a permanent place in the rotation.",
  protects:["Achilles and calf injury when you start or return to running and plyometrics.","A recently healed foot, by loading it progressively instead of all at once.","Ankle power and balance in old age; calf strength predicts walking speed later in life."],
  steps:["Stand on one foot, fingertips on a wall for balance only.","Rise as high as you can onto the ball of the foot, weight over the big toe.","Lower over a slow 3 seconds until the heel is just above the floor.","10 to 12 reps, then switch. Two sets if time allows.","Progress by standing on a step so the heel can drop below the toes, then by adding weight in a backpack."],
  pitfalls:["Rolling the ankle outward so the weight sits on the little toe side, which overloads the outer edge of the foot. Keep the pressure through the big toe.","Bouncing. The slow lowering is where the tendon adapts.","Pushing through sharp pain in the outside of the foot. Dull muscle burn is fine; bone pain is not."],
  evidence:"After a foot injury, the progression calf raises → hops → running → cutting is standard rehabilitation practice rather than a trialled protocol. Grip and leg strength both associate with lower mortality in large cohorts."},

 {id:"bdj1",name:"Ba Duan Jin 1: Hold up the sky",slot:"mind",secs:60,equip:[],grade:"moderate",
  search:yt("ba duan jin two hands hold up the heavens tutorial"),
  why:"The first of the Eight Brocades, and the start of learning the one mind-body set with real trial evidence. It lengthens the whole front of the body and decompresses the spine while coordinating breath, gaze and movement.",
  protects:["Blood pressure: the one-year trial found daily Ba Duan Jin matched brisk walking.","Thoracic extension and shoulder range, counteracting hours of hunching.","Attention: a short sequence you learn by heart becomes a moving meditation."],
  steps:["Stand feet shoulder width, knees soft. Interlace the fingers in front of the lower belly, palms up.","Breathing in, lift the hands up the centre line past the chest and face, then turn the palms to face the sky and press up, arms straight.","Let the gaze follow the hands up, then return it forward. Rise onto the balls of the feet if balance allows.","Breathing out, release the fingers and float the arms out and down in a wide arc back to the belly.","6 to 8 slow repetitions. Each breath sets the speed; the movement never rushes the breath."],
  pitfalls:["Arching the lower back to press higher. Length comes from the ribs and shoulders, with the belly gently drawn in.","Shrugging. The arms go up; the shoulders stay down.","Learning several Brocades at once. Own this one first; the next comes when it is offered."],
  evidence:"BLESS trial (JACC 2026, n = 216, 52 weeks): daily Ba Duan Jin lowered office systolic BP by about 5 mmHg, comparable to brisk walking at one year. Meta-analyses in older adults show balance gains (Berg +4.8 points) with high heterogeneity and mostly Chinese, unblinded trials."},

 {id:"zhan",name:"Standing post (Zhan Zhuang)",slot:"mind",secs:120,equip:[],grade:"thin",
  search:yt("zhan zhuang standing meditation beginner"),
  why:"Standing meditation from the internal martial arts: posture, breath and attention trained as one thing. It is the closest thing here to meditation that is also physical practice, and it links directly to the stance work in many martial arts.",
  protects:["Postural endurance in the legs, feet and deep trunk, built by standing still rather than moving.","Habitual over-tension (shoulders, jaw, belly), which the practice teaches you to notice and release.","A restless mind; two minutes of standing with nowhere to go is attention training with no app."],
  steps:["Feet parallel, shoulder width. Knees unlocked, not bent. Pelvis neutral, tailbone heavy.","Imagine the crown of the head suspended by a thread. Chin slightly in. Tongue to the roof of the mouth.","Raise the arms in front of the chest as if holding a large ball; elbows below the hands, shoulders soft.","Breathe low and slow. Scan from head to feet and release anything that is working but does not need to: forehead, jaw, shoulders, belly, buttocks, feet.","When attention drifts, return to the sensation of the feet on the floor. Hold for the whole timer; lower the arms slowly and stand a moment longer."],
  pitfalls:["Arms held with the shoulders. If they burn after 30 seconds, lower them to belly height.","Locking the knees or sinking too low. Soft and tall.","Treating discomfort as failure. Trembling legs and a wandering mind are the practice working, not failing."],
  evidence:"Almost no published outcome trials of Zhan Zhuang (a college-student protocol and a registered 'Daoist Zhanzhuang and flourishing' trial exist, without results). The rationale is borrowed from tai chi and standing-balance evidence; the risk is nil."},

 {id:"splitsquat",name:"Split squat (deep)",slot:"legs",secs:90,equip:[],grade:"thin",
  search:yt("ATG split squat beginner progression"),
  why:"Knee and hip range built under load, which research shows improves flexibility as well as stretching does while also strengthening. The deep front-knee position loads the patellar tendon and quad near full flexion, and the back leg gets a hip-flexor stretch with the glute working.",
  protects:["Knee tendon capacity for running, jumping and the deep-knee positions of martial arts.","Hip-flexor length, actively, as a complement to the kneeling stretch.","Ankle dorsiflexion, which the squat and the sit-rise both depend on."],
  steps:["Take a long split stance. At first, put the front foot on a low step or thick book to reduce the ankle demand.","Keeping the back leg straight and its glute squeezed, bend the front knee and drive it forward over the toes.","Go as deep as pain-free range allows; the goal over months is hamstring touching calf.","Push back up through the whole front foot. 6 to 8 slow reps per side.","Hold something for balance if needed; balance is not the point here."],
  pitfalls:["Front heel lifting. Elevate the foot more or shorten the depth until the ankle allows it.","A pinch at the front of the hip or knee: reduce depth. Muscle stretch is fine; joint pinch is not.","Progressing by depth before control. Only lower the step when the current depth is smooth and pain-free for a week.","Believing the 'knees over toes' branding has trial evidence. The principle is sound; the programme is untested."],
  evidence:"Restricting forward knee travel reduces knee torque about 22% but raises hip torque over tenfold (Fry 2003), and deep squatting is not harmful to healthy knees with progressive loading (Hartmann 2013). The ATG programme itself has only an uncontrolled 14-person self-report study."},

 {id:"wrist",name:"Wrist prep",slot:"wrists",secs:60,equip:["floor"],grade:"thin",
  search:yt("handstand wrist warm up routine"),
  why:"Handstands and cartwheels late in life need wrists that have been loaded gently for decades. Wrists have little muscle around them and their bones and ligaments adapt slowly, so a minute a day now is cheap insurance.",
  protects:["Wrist pain when you take up handstand or floor work.","Fall injuries; the wrist is what you land on.","Forearm tendon health for typing, tools and grip."],
  steps:["On all fours, hands flat under the shoulders, fingers spread.","Rock the body forward until the shoulders pass the wrists, then back. 10 slow rocks.","Rock side to side, 10 each way.","Palm lifts: keep the fingers and knuckles down and lift the heel of the hand, 10 times.","Turn the hands so the fingers point back toward the knees, palms down, and rock gently back. Then backs of the hands on the floor, fingers pointing in, light pressure. 20 seconds each."],
  pitfalls:["Full bodyweight on day one. Start with the hips back toward the heels so the wrists carry little, and move forward over weeks.","Sharp pain on the thumb side or the back of the wrist: reduce load or range. Stretch sensation in the forearm is normal.","Skipping it because it feels trivial. It is the one thing in the routine that only pays off years later."],
  evidence:"Practitioner-level, from gymnastics and hand-balancing coaching. Connective tissue adapts over months to years (general tendon-loading literature); no trials of wrist prep as a stand-alone intervention."},

 {id:"tib",name:"Tibialis raises",slot:"legs",secs:60,equip:[],grade:"thin",
  search:yt("tibialis raise wall"),
  why:"The muscle on the front of the shin decelerates the foot on every step and landing. It is almost never trained, and strengthening it is cheap protection for shins, ankles and knees whenever you run and jump.",
  protects:["Shin splints and anterior ankle strain when running volume increases.","Landing mechanics; a strong tibialis slows the foot slap that loads the knee.","Ankle dorsiflexion control for the sit-rise and the deep squat."],
  steps:["Lean your back against a wall, feet about 30 cm out, legs straight.","Lift both forefeet toward the shins as high as you can, heels staying on the floor.","Lower slowly. 15 to 20 reps.","Progress by moving the feet further from the wall, then to one leg at a time."],
  pitfalls:["Bending the knees to help. Keep them straight so the tibialis does the work.","Stopping at the first burn. The burn is the point; stop at sharp pain only."],
  evidence:"Little outcome evidence for isolated tibialis training; the rationale is biomechanical (deceleration and landing) and it is popular in the Knees Over Toes system, which is itself untested. Low risk, low cost."},

 {id:"bdj2",name:"Ba Duan Jin 2: Draw the bow",slot:"mind",secs:60,equip:[],grade:"moderate",
  search:yt("ba duan jin drawing the bow tutorial"),
  why:"The second Brocade. It loads the legs in a wide stance while opening the chest and shoulders, with gaze and breath tied to the movement. Together with the first it makes a two-minute moving meditation you can do anywhere.",
  protects:["Leg strength and hip width from the horse stance, the same base many martial arts use.","Chest and shoulder opening against the forward posture of desk work.","Blood pressure and balance, via the same trial base as the full set."],
  steps:["Step the left foot out into a wide stance and sink into a comfortable horse stance, knees over toes, back tall.","Cross the hands in front of the chest, left hand outside.","Breathing out, extend the left arm to the left with the index finger pointing up, while the right hand pulls back to the right shoulder as if drawing a bow. Turn the head to look along the pointing finger.","Breathing in, bring the hands back to the chest and rise slightly.","Repeat to the right. 4 to 6 each side, then step the feet together."],
  pitfalls:["Knees collapsing inward in the stance. Push them gently out over the toes.","Lifting the shoulders when drawing the bow. The elbow pulls back; the shoulder stays down.","Leaning the torso toward the pointing arm. Stay upright and let the turn come from the neck and upper back."],
  evidence:"Same base as Brocade 1: the BLESS blood-pressure trial (JACC 2026) and balance meta-analyses in older adults. The individual movements have not been tested separately."},

 {id:"wgs",name:"World's greatest stretch",slot:"hips",secs:90,equip:["floor"],grade:"thin",
  search:yt("world's greatest stretch tutorial"),
  why:"Hip flexors, hamstrings and upper-back rotation in one moving sequence. It is the most efficient single drill for days when the hips get one slot, and the rotation is deliberately placed in the thoracic spine, away from your lower back.",
  protects:["Hip and thoracic range for rotation sports and martial arts, so the lumbar spine does not have to supply the twist.","Hamstring and hip-flexor stiffness after long sitting."],
  steps:["Step into a long lunge, right foot forward, both hands on the floor inside the right foot. Back knee off the floor or down, as you prefer.","Drop the right elbow toward the instep of the right foot, keeping the back long. Hold 2 seconds.","Rotate the right arm up toward the ceiling, turning the chest open, eyes following the hand. Hold 2 seconds.","Return the hand to the floor. Repeat 4 times, then switch legs.","Optional finish: straighten the front leg and sit the hips back for a hamstring stretch, 10 seconds."],
  pitfalls:["Twisting from the lower back. The rotation should feel between the shoulder blades; if the lumbar spine twists, reduce the range.","Collapsing the back knee inward. Keep the back leg long and active.","Rushing. Each position gets a breath."],
  evidence:"Dynamic mobility sequences improve short-term range of motion; no long-term outcome trials. The thoracic-rotation emphasis follows the general spine-sparing logic of keeping rotation out of the lumbar spine under load (McGill)."},

 {id:"shoulderCARs",name:"Shoulder circles (CARs)",slot:"shoulders",secs:60,equip:[],grade:"thin",
  search:yt("shoulder CARs controlled articular rotations"),
  why:"A slow, deliberate circle through the shoulder's full active range. It is best understood as a daily self-check: the morning you cannot make the circle you made last week, something has changed and you know it early.",
  protects:["Loss of overhead and behind-the-back shoulder range as you age.","Early detection of shoulder stiffness before it becomes a problem."],
  steps:["Stand tall. Brace the trunk lightly and make a fist with the hand you are not moving.","With a straight arm, slowly raise the working arm forward and up as far as it goes without the torso moving.","At the top, rotate the palm outward and continue the arm back and down behind you in the largest circle it can make.","3 slow circles each direction, each side. Each circle takes 10 to 15 seconds.","Think of pushing through thick water; the effort is in moving slowly at the edge of range."],
  pitfalls:["Letting the torso lean or arch to make the circle bigger. The circle is only as big as the shoulder itself allows.","A pinch at the front or top of the shoulder: shrink the circle at that point and go around it.","Believing the 'lubricates the joint and slows degeneration' story. That claim has no trial evidence; the drill is still useful as range work and as a check."],
  evidence:"No peer-reviewed study of controlled articular rotations on synovial fluid, cartilage or joint degeneration; the sources are clinic blogs. Joint movement does circulate synovial fluid in general physiology, which is true of any movement."},

 {id:"squat_hold",name:"Deep squat hold",slot:"legs",secs:60,equip:[],grade:"thin",
  search:yt("deep squat hold mobility"),
  why:"The resting squat is the position most of humanity used for most of history and most desk workers lose by 30. Holding it loads ankles, knees and hips together and is the simplest test of whether all three still work.",
  protects:["Ankle, knee and hip range as a unit.","Lower-back load in lifting, by making a deep hip position available.","Floor living in old age: getting down to and up from the floor starts with being able to squat."],
  steps:["Feet a little wider than hip width, toes turned out slightly. Put a book or rolled towel under the heels if they lift.","Sink as low as you can with a long spine, weight in the middle of the feet.","Press the elbows gently against the inside of the knees to open the hips. Breathe slowly.","Hold 20 seconds, stand, shake out, repeat 3 times.","Progress by lowering the heel support over weeks, and by holding longer."],
  pitfalls:["Rounding the lower back into a C. A small round at the bottom is normal; a collapsed back is not. Raise the heels more.","Knees caving in. Elbows push them out.","Forcing the heels down on day one. Ankle range takes months; use the support."],
  evidence:"Deep squatting is not harmful to healthy knees with progressive loading (Hartmann 2013, review). Loaded range work improves flexibility as well as stretching does (Afonso 2021). No long-term outcome trials of squat holds."},

 {id:"owl",name:"Owl looks back",slot:"spine",secs:60,equip:[],grade:"thin",
  search:yt("ba duan jin wise owl gazes backwards"),
  why:"Neck rotation and upper-back opening from the Eight Brocades, a two-minute antidote to screens. It also trains the eyes and neck to move independently of the shoulders, which matters for balance later in life.",
  protects:["Neck stiffness and forward-head posture from screen work.","Cervical rotation, which you need to check over your shoulder on a bike for the rest of your life.","Upper-trapezius over-tension; the movement teaches the shoulders to stay down while the head turns."],
  steps:["Stand tall, feet shoulder width, arms hanging with the palms turned outward.","Breathing out, turn the head slowly to look as far behind you as you can over one shoulder. Let the eyes lead and go a little further than the neck.","Hold 3 seconds, breathing.","Breathing in, return to centre. Repeat to the other side. 5 each side.","Keep the shoulders down and the chest open throughout; the palms-out position helps."],
  pitfalls:["Turning the whole torso. The shoulders face forward; the rotation is in the neck and upper back.","Tilting the head back while turning. Keep the chin level.","Dizziness: slow down, and skip the eye lead."],
  evidence:"Part of the Ba Duan Jin set used in the blood-pressure and balance trials; not tested on its own. Neck mobility exercise has small benefits for neck pain in reviews (NCCIH on yoga and neck pain, 2019)."},

 {id:"hollow",name:"Hollow hold",slot:"core",secs:60,equip:["floor"],grade:"thin",
  search:yt("hollow body hold tutorial"),
  why:"The body shape behind handstands, cartwheels and clean running posture: ribs down, pelvis tucked, whole trunk stiff. It is flexion-biased, so it comes late in the routine after the spine has moved, and the holds stay short.",
  protects:["Trunk stiffness for inverted skills and for absorbing landings.","Lower-back arch under overhead load (handstands, pressing), by training the opposite position."],
  steps:["Lie on the back. Press the lower back firmly into the floor and keep it there for the whole exercise.","Lift the shoulders and head slightly, arms by the sides or reaching past the hips.","Lift the legs with the knees bent at first; straighten them as you get stronger, keeping the lower back down.","Hold 15 seconds, rest 10, repeat 3 times. Breathe throughout.","Progress by straightening the legs, then by raising the arms overhead."],
  pitfalls:["The lower back lifting off the floor. That is the fail point; bend the knees or raise the legs higher until it stays down.","Long holds in the morning. Keep them short; the discs are still settling.","Pulling on the neck. The head floats; the belly does the work."],
  evidence:"Gymnastics and strength-coaching practice; the biomechanical logic is uncontroversial (anti-extension trunk stiffness). No outcome trials. Placed late in the routine in deference to the morning-flexion findings (Adams & Dolan 1987; Snook 1998)."},

 {id:"bdj_full",name:"Ba Duan Jin, full set (follow-along)",slot:"video",secs:720,equip:[],grade:"moderate",
  search:yt("ba duan jin eight brocades follow along 12 minutes"),
  why:"The whole Eight Brocades, once you have met the individual pieces. This is the daily sequence the one-year blood-pressure trial used, the most-studied qigong form, and the one most realistic to learn alone from video. It is the mind-body core of the routine on follow-along days.",
  protects:["Blood pressure, balance, flexibility, grip and sleep quality, per the trials in older and hypertensive adults.","A single lifelong practice you will still be able to do at 80, which is the point of choosing it now."],
  steps:["Open the video and follow it start to finish. Eight movements, about 12 minutes.","Stand where you have arm's length of space in every direction. Barefoot or flat shoes.","Match the teacher's pace exactly; slow is correct. Breathe through the nose, out on the effort.","Keep the knees soft and the spine long in every movement. If a movement is unfamiliar, do a smaller version of it rather than skipping.","Afterwards, stand still for 30 seconds and notice the body before moving on."],
  pitfalls:["Speeding up to finish. The breath sets the pace; a rushed set is a different exercise.","Forcing depth in the squatting movements (Brocade 5 and 7). Go to comfortable range.","Changing teachers every week. Pick one version and learn it; variety can come later."],
  evidence:"BLESS trial (JACC 2026): 216 adults with elevated BP, Ba Duan Jin five days a week for a year, systolic BP down about 5 mmHg in-office, comparable to brisk walking. Meta-analyses (19 RCTs; 17 RCTs) show gains in balance, sleep, grip and BP, mostly in older adults, with low trial quality."},

 {id:"yoga_flow",name:"10-minute morning yoga (follow-along)",slot:"video",secs:600,equip:["floor"],grade:"moderate",
  search:yt("10 minute morning yoga stretch beginner"),
  why:"A change of texture on follow-along days: flowing, warm, and a different movement vocabulary from the qigong. Yoga has moderate evidence for back pain, stress and small cardiovascular benefits, and a short gentle flow is the low-risk way to get them.",
  protects:["Perceived stress; reviews in healthy adults consistently find reductions.","Chronic low-back pain, with effects equal to other back exercise.","Flexibility and balance, as a general stimulus."],
  steps:["Open the video and follow it on a mat.","Soften or skip any deep standing forward fold in the first hour after waking; bend the knees generously instead.","Stay within comfortable range in every pose; this is a morning flow, not a flexibility session.","Finish with one minute of slow breathing on your own, seated or lying down."],
  pitfalls:["Loaded deep forward bends early in the morning, which stress the discs; this is the one place the yoga and the back advice conflict.","Inversions and fast flows while back or nerve pain is undiagnosed. Keep to gentle sequences until it has been examined.","Pushing to match the teacher's range. Yoga's injury rate is higher in unsupervised practice; the camera cannot correct you."],
  evidence:"Cochrane 2022 (21 RCTs): yoga gives small improvements in chronic low-back pain, no better than other back exercise, with more minor adverse events than no exercise. A 64-RCT meta-analysis found modest blood-pressure and lipid improvements. Perceived stress fell in 12 of 12 studies in healthy adults (NCCIH)."},

 {id:"ankleCARs",name:"Ankle circles",slot:"legs",secs:45,equip:[],grade:"thin",
  search:yt("ankle CARs mobility"),
  why:"Active ankle range in every direction, with the standing leg balancing as a bonus. Especially useful after a foot or ankle injury, when range lost during immobilisation needs reminding.",
  protects:["Ankle stiffness after injury or immobilisation.","Ankle sprains, by keeping the end ranges active and controlled.","Balance on the standing side."],
  steps:["Stand on one leg, a fingertip on a wall if needed. Lift the other foot a little.","Draw the biggest slow circle the ankle can make: toes up, out, down, in. 5 circles.","Reverse direction, 5 circles. Then switch feet.","Keep the knee and hip still; all the movement is in the ankle."],
  pitfalls:["Making the circle with the whole leg. Hold the shin still with a hand if that helps.","Small fast circles. Big and slow."],
  evidence:"Practitioner-level mobility work; no trials specific to ankle CARs. Ankle range and balance training are standard after foot and ankle injuries."},

 {id:"band_pull",name:"Band pull-aparts",slot:"posture",secs:60,equip:["band"],grade:"thin",
  search:yt("band pull apart form"),
  why:"Endurance for the upper back and the back of the shoulder, the muscles that hold the shoulder blades where they belong. A staple of nearly every shoulder-health programme and a good use of a light resistance band.",
  protects:["Rounded-shoulder posture and the impingement-type aches that come with it.","Shoulder stability for pulling, pressing and hanging."],
  steps:["Hold a light band at shoulder height, hands shoulder width, arms straight, palms down.","Pull the band apart until it touches the chest, squeezing the shoulder blades together.","Return slowly over 2 seconds. 15 reps, rest, 15 more.","Vary the grip (palms up) or the height on alternate days."],
  pitfalls:["Shrugging to the ears. The shoulder blades move back and down, not up.","Using a band so heavy that the arms bend. Light band, strict form, high reps.","Arching the lower back. Ribs down."],
  evidence:"Practitioner-level; appears in most rotator-cuff and scapular rehabilitation programmes. No outcome trials of the exercise in isolation."},

 {id:"pogo",name:"Pogo hops",slot:"legs",secs:60,equip:[],grade:"moderate",
  search:yt("pogo hops ankle stiffness drill"),
  why:"Impact is what builds bone, and peak bone mass is set in your 20s. Light, quiet hops are the smallest dose of impact that counts, and the gateway back to running and jumping after a foot injury. Gated after an injury: only once the foot has been pain-free in daily life for a month.",
  protects:["Bone density in the legs and spine, banked while peak bone mass is still being built in the 20s.","Achilles stiffness and spring for running and martial arts.","Fracture risk later in life, through the bone banked now."],
  steps:["Stand tall on both feet, hands on hips or relaxed.","Bounce with nearly straight knees, using the ankles like springs. Small, quick, quiet hops.","15 hops, rest 20 seconds, repeat 3 times.","Land on the balls of the feet and let the heels kiss the floor. Quiet landings mean good landings.","Progress over weeks to single-leg hops, then to skipping rope."],
  pitfalls:["Starting before an injured foot is ready. If daily walking still produces any outside-foot ache, stay with calf raises.","Loud, heavy landings. Reduce height until they are quiet.","Doing it on a hard floor in socks. Shoes or a firm mat, barefoot only once the feet are strong."],
  evidence:"In 38 men with low bone density, 12 months of resistance training or jump training each raised lumbar spine BMD about 1.3% (Hinton 2015). High-intensity resistance plus impact improved BMD in the LIFTMOR trial. Peak bone mass is reached in the 20s, later in men; a 10% higher peak is modelled to delay osteoporosis by about 13 years."},

 {id:"gmb_daily",name:"GMB 4-minute animal flow (follow-along)",slot:"video",secs:240,equip:["floor"],grade:"thin",
  search:yt("GMB fitness 4 minute daily routine bear monkey frogger crab"),
  why:"Four crawling patterns, one minute each: bear, monkey, frogger, crab. It warms wrists, shoulders, hips and ankles together and it is playful, which is worth something first thing in the morning. A short follow-along for days when a full qigong set is too long.",
  protects:["Wrist and shoulder loading tolerance for floor skills.","Whole-body coordination and hip range in positions you otherwise never visit."],
  steps:["Open the video and follow it; each movement runs for one minute.","Keep the movements small and controlled at first; range grows over weeks.","Breathe continuously and keep the neck relaxed.","Stop at any sharp wrist pain and do the wrist prep instead."],
  pitfalls:["Rushing the crawls into cardio. This is skill and joint work; slow is better.","Full weight on cold wrists. Do a few wrist rocks first if it is the first thing of the day."],
  evidence:"Practitioner-level (GMB's head coach is a former gymnast with decades of martial-arts practice). No trials; low risk when kept slow."},

 /* ---------- Posture (upper crossed pattern: rounded shoulders, forward head, tight chest, flat upper back) ---------- */
 {id:"doorway",name:"Doorway chest opener",slot:"posture",secs:90,equip:[],grade:"moderate",
  search:yt("doorway pec stretch posture"),
  why:"The chest-opening half of the posture fix: shoulders that roll forward are held there partly by short pectoral muscles. Lengthening them in a doorway is the simplest chest opener there is and needs no equipment.",
  protects:["Rounded-shoulder posture, by removing the front-side pull that drags the shoulders in.","Shoulder impingement-type aches that come with a forward shoulder position.","The 'protective curl': an open chest is the posture of the guard being down, and the body feeds that back to the mind."],
  steps:["Stand in a doorway. Place the forearms on the frame with the elbows a little below shoulder height.","Step one foot through and lean the chest forward until you feel a stretch across the front of the shoulders and chest. Keep the ribs down.","Hold 30 seconds breathing slowly. Do not push into the end; let the stretch arrive.","Raise the elbows to above shoulder height and repeat 30 seconds; this targets a different part of the chest.","Finish by stepping out and rolling the shoulders back and down once, slowly."],
  pitfalls:["Arching the lower back to get a bigger stretch. Keep the pelvis tucked and the stretch in the chest.","Tingling in the hands: back off, the nerves are being pulled, not the muscle.","Doing only this and not the strengthening. A stretched chest without a stronger back returns to the curl within hours."],
  evidence:"Therapeutic exercise (stretching plus strengthening) measurably reduces rounded shoulders, forward head and thoracic kyphosis in a 2024 meta-analysis of 22 studies on upper crossed syndrome (Sepehri et al., BMC Musculoskeletal Disorders). Whether posture itself causes pain is contested; the clearer effect is on the posture angles."},

 {id:"chin_tuck",name:"Chin tucks",slot:"posture",secs:60,equip:[],grade:"moderate",
  search:yt("chin tuck exercise forward head posture"),
  why:"Forward head posture puts the ear well in front of the shoulder: the head is carried forward and the neck leaves the upper back at an angle. The head weighs about 5 kg and every centimetre forward multiplies the load on the neck. Chin tucks train the deep neck flexors that hold the head over the spine, and they are the most studied exercise for exactly this.",
  protects:["Forward-head posture after screen and desk work.","Neck pain and tension headaches, where the trials show the clearest benefit.","Upper-trapezius over-use, which otherwise takes over the job of holding the head."],
  steps:["Stand or sit tall, eyes level. Place two fingertips lightly on the chin.","Glide the chin straight back, making a double chin, without tilting the head up or down. The back of the neck lengthens.","Hold 5 seconds, release gently. 10 repetitions.","Harder version: lie on the back, tuck the chin and lift the head 2 cm off the floor, hold 5–10 s.","Use the standing version as a reset any time you notice the head has crept forward."],
  pitfalls:["Nodding the chin down instead of gliding it back. The eyes stay level.","Forcing the hold with the jaw clenched. The front of the neck works; the jaw stays soft.","Pain or dizziness: stop; neck exercise should never hurt."],
  evidence:"A meta-analysis of 7 RCTs (627 people) found exercise significantly improves the craniovertebral angle, the standard forward-head measure, with strong (level 1a) evidence; neck pain improved too (Sheikhhoseini et al., JMPT 2018). Most trials were in people with neck pain."},

 {id:"tspine_ext",name:"Upper-back extension over a roll",slot:"posture",secs:90,equip:["floor"],grade:"moderate",
  search:yt("thoracic extension foam roller"),
  why:"A rounded upper back is the hinge the whole posture pattern hangs on: if the thoracic spine cannot extend, the shoulders cannot sit back and the head cannot sit over the spine no matter how hard you try. This opens that hinge with gravity doing the work, and it is the partner of the chin tuck: one frees the hinge, the other re-stacks the head on it.",
  protects:["Thoracic kyphosis, the rounding of the upper back that increases with every decade of sitting.","Overhead shoulder range, which depends on the upper back extending.","Breathing depth: an extended rib cage expands further."],
  steps:["Lie on the back with a foam roller, or a tightly rolled towel, across the upper back at the level of the shoulder blades. Knees bent, feet flat.","Support the head with the hands, elbows forward. Keep the ribs down so the lower back does not arch.","Breathe out and let the upper back drape over the roll for 3 slow breaths.","Lift slightly, move the roll 3 cm up or down, and repeat. Work from the bottom of the shoulder blades to the top, 4 to 5 positions.","Without a roll: sit on a chair, hands behind the head, and arch the upper back over the top of the backrest, 8 slow reps."],
  pitfalls:["Rolling down onto the lower back. The roll stays between the bottom of the shoulder blades and the base of the neck.","Pulling on the head with the hands. The hands only support it.","Extending from the lower back instead of the upper. Keep the ribs down and the belly lightly engaged."],
  evidence:"Thoracic extension and global postural exercise reduce kyphosis angle in trials and the 2024 upper-crossed-syndrome meta-analysis (Sepehri et al.). The size of change is modest (a few degrees); the functional gain in overhead range is what you will notice first."},

 {id:"ytw",name:"Prone Y-T-W raises",slot:"posture",secs:90,equip:["floor"],grade:"moderate",
  search:yt("prone Y T W exercise lower trapezius"),
  why:"The strengthening half of the fix: the muscles between and below the shoulder blades that hold the shoulders back are weak in almost everyone who sits, and no amount of stretching replaces them. Three arm positions on the floor cover all of them with bodyweight only.",
  protects:["Rounded shoulders, by making the open position the body's default rather than a willed act.","Shoulder blade control for hanging, pressing and handstand work.","Neck tension, by giving the lower trapezius a share of the work the upper trapezius usually does alone."],
  steps:["Lie face down, forehead on a folded towel, arms overhead in a Y with thumbs up.","Squeeze the shoulder blades down and together, lift the arms a few centimetres, hold 2 seconds, lower. 8 reps.","Move the arms out to a T, thumbs up. 8 lifts, same squeeze.","Bend the elbows to make a W, thumbs up. 8 lifts, pulling the elbows toward the back pockets.","Rest 20 seconds and repeat the set if time allows. The lifts are small; the squeeze is the exercise."],
  pitfalls:["Shrugging toward the ears. The shoulder blades go down and in, not up.","Lifting the chest off the floor. Only the arms move.","Going for height. Two centimetres with a hard squeeze beats a high swing."],
  evidence:"Strengthening the scapular retractors and lower trapezius is the common element of the programmes that improved rounded shoulders in the upper-crossed-syndrome meta-analysis (Sepehri 2024, 22 studies). Y-T-W itself is a standard rehab prescription without its own trials."},

 {id:"facepull",name:"Band face pulls",slot:"posture",secs:60,equip:["band"],grade:"thin",
  search:yt("band face pull form"),
  why:"The best single band exercise for the back of the shoulder and the external rotators, the muscles that turn the shoulders out and back. It pairs with the pull-aparts to make the band worth owning.",
  protects:["Shoulder internal-rotation posture (palms facing backwards when you stand relaxed is the tell).","Rotator-cuff health for pressing and hanging.","The 'guard up' shoulder position; this is the muscle that un-rounds it."],
  steps:["Anchor the band at face height (a door handle or hook), or loop it around the pull-up bar.","Hold the ends with palms facing each other, step back until the band is taut, arms straight.","Pull toward the face, elbows high and wide, hands finishing beside the ears with the thumbs pointing back.","Pause 1 second with the shoulder blades squeezed, return slowly. 12 to 15 reps, 2 sets."],
  pitfalls:["Leaning back to pull. Stand tall; if the band is too strong, step closer.","Elbows dropping below the hands. High elbows are what make it a face pull rather than a row.","Rushing. The slow return is half the benefit."],
  evidence:"Practitioner-level, from strength coaching and shoulder rehabilitation; it is a staple in both, but not trialled on its own. General rotator-cuff and scapular strengthening evidence applies."},

 {id:"glute_bridge",name:"Glute bridge",slot:"hips",secs:60,equip:["floor"],grade:"moderate",
  search:yt("glute bridge technique"),
  why:"Posture is not only the shoulders. A pelvis tipped forward (belly out, lower back arched) is the lower half of the same pattern, and it usually means the glutes are asleep and the hip flexors are doing their job. The bridge wakes the glutes without loading the spine.",
  protects:["Anterior pelvic tilt and the lumbar arch that goes with it.","Lower-back strain in standing and lifting, by giving the hips the extension job.","Hip-flexor dominance, which pairs with the kneeling stretch from the other direction."],
  steps:["Lie on the back, knees bent, feet flat hip-width apart, arms at the sides.","Breathe out, tuck the pelvis slightly so the lower back touches the floor, then push through the heels to lift the hips.","Stop when the body is a straight line from shoulders to knees. Squeeze the glutes at the top for 2 seconds.","Lower slowly. 12 to 15 reps.","Progress by lifting on one leg, or by pausing 5 seconds at the top."],
  pitfalls:["Lifting too high and arching the lower back. The glutes finish the movement, not the spine.","Pushing through the toes. Heels down, toes light.","Hamstring cramp: move the feet a little closer to the hips."],
  evidence:"Glute strengthening is standard in programmes for anterior pelvic tilt and low-back pain; the bridge is low load and well tolerated. Direct trials on resting pelvic tilt are small; the hip-extension strength gain is well established."},

 {id:"posture_wall",name:"Wall reset & tall walk",slot:"posture",secs:60,equip:[],grade:"thin",
  search:yt("wall posture check exercise stand tall"),
  why:"The awareness rep, a posture interrupt: the strengthening and stretching change what is possible, this changes what you actually do with it. One minute against a wall gives the body a reference for 'open', and the walk carries it out of the door.",
  protects:["The slow return to the curl during the day; a felt reference is what makes catching it possible.","Self-image: posture and how you feel about yourself run in both directions."],
  steps:["Stand with heels about 5 cm from a wall. Let the buttocks, upper back and the back of the head touch it. Chin level.","Draw the lower ribs down so the gap behind the lower back is about a hand's thickness, not more.","Let the shoulders fall back and down toward the wall without forcing. Glide the chin back so the ear sits over the shoulder. Breathe here for 30 seconds and memorise the feeling.","Step away and walk around the room for 30 seconds keeping that shape: tall, chest open, unhurried, taking up space.","Through the day, use the same cue, 'wall', to reset when you notice the shoulders have rolled in."],
  pitfalls:["Jamming the lower back flat or the head hard against the wall. This is a reference, not a brace.","Puffing the chest out and holding the breath. Open means relaxed and tall, not military.","Expecting it to hold on its own. It holds only once the strengthening makes it cheap."],
  evidence:"Awareness-based postural cueing is part of most trialled posture programmes but has no separate evidence. The felt shift from an expansive posture replicates in the literature; the hormonal claims around 'power posing' did not. Treat it as practice, not physiology."},
];
